from collections.abc import Collection

def check_subset(sub, main):
    """
    Check if all elements in 'sub' are contained within 'main'.
    Works for any collections (e.g., lists, sets, tuples).
    """
    # Convert to collections.Counter if elements are hashable, else fallback to checking membership
    try:
        from collections import Counter
        sub_count = Counter(sub)
        main_count = Counter(main)
        return all(main_count[element] >= count for element, count in sub_count.items())
    except TypeError:
        # Elements not hashable, fallback to checking membership one by one
        main_list = list(main)
        for element in sub:
            try:
                main_list.remove(element)
            except ValueError:
                return False
        return True
```

