    """
    Find the power x such that base ** x = value.
    Returns the exponent x if it exists, otherwise raises ValueError.
    """
    import math

    if base <= 0:
        raise ValueError("Base must be positive and non-zero.")
    if value <= 0:
        raise ValueError("Value must be positive and non-zero.")

    return math.log(value, base)
