import re

def anti_shuffle(s):
    def sort_word(word):
        # Separate trailing punctuation from the word
        match = re.match(r"([A-Za-z]+)([^A-Za-z]*)$", word)
        if not match:
            # No letters, return as is
            return word
        letters, punct = match.groups()
        # If the first letter is uppercase, keep it in front after sorting rest
        if letters and letters[0].isupper():
            first = letters[0]
            rest = ''.join(sorted(letters[1:]))
            return first + rest + punct
        else:
            # all lowercase or no uppercase start - sort all letters
            return ''.join(sorted(letters)) + punct

    # Split string by spaces, preserving spaces
    parts = re.split(r'(\s+)', s)
    result = []
    for part in parts:
        if part.isspace() or part == '':
            # spaces or empty parts remain untouched
            result.append(part)
        else:
            result.append(sort_word(part))
    return ''.join(result)
```

