def will_it_fly(q, w):
    total_weight = sum(q)
    if total_weight > w:
        return False
    n = len(q)
    if n == 1:
        return True
    mid = n // 2
    if n % 2 == 1:
        left = q[:mid]
        right = q[mid+1:]
    else:
        left = q[:mid]
        right = q[mid:]
    return sum(left) == sum(right)
